-- Name: bus_chain_configs_bump_version(); Type: FUNCTION; Schema: kernel; Owner: -
--

CREATE FUNCTION kernel.bus_chain_configs_bump_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.reactors IS DISTINCT FROM OLD.reactors OR NEW.enabled IS DISTINCT FROM OLD.enabled THEN
    NEW.version := OLD.version + 1;
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;


